class User {
  #id;
  constructor(name, id) {
    this.name = name;
    this.#id = id;
  }
  greet() {
    return `Привет, ${this.name}`;
  }
  get id() {
    return this.#id;
  }
}

class Admin extends User {
  constructor(name, id, role) {
    super(name, id);
    this.role = role;
  }
  greet() {
    return `${super.greet()} (${this.role})`;
  }
}

console.log(new Admin("Ada", 1, "editor").greet());
